<div class="settings-tabs"><?php foreach($settingsSections as $s=>$unused): ?><a href="<?= e(url('admin/settings',['section'=>$s])) ?>" class="<?= $section===$s?'active':'' ?>"><?= e(ucfirst($s)) ?></a><?php endforeach ?></div><?php if($section==='razorpay'): ?><div class="panel mb-4"><h2>Connect Razorpay</h2><p>Use test keys first. Add the webhook URL below in your Razorpay dashboard and subscribe to <code>payment.captured</code> and <code>payment.failed</code>. Enable automatic capture. Use a separate webhook secret and enter the same value here.</p><code class="break-all"><?= e(url('payment/webhook')) ?></code><p class="mt-3 mb-0">Secrets are encrypted in the database and never sent to the browser. Leave secret fields empty to retain them. For live payments, use an HTTPS domain, matching live keys and a tested webhook.</p><a href="https://razorpay.com/docs/payments/server-integration/php/integration-steps/" target="_blank" rel="noopener">Razorpay integration guide ↗</a></div><?php endif ?><?php if($section==='policies'): ?><p class="admin-hint">Enter your approved business policies. Content is displayed as plain text with preserved line breaks.</p><?php endif ?><form method="post" action="<?= e(url('admin/settings')) ?>" enctype="multipart/form-data" class="panel"><?= csrf() ?><input type="hidden" name="section" value="<?= e($section) ?>"><div class="form-grid"><?php foreach($fields as $field): $value=setting($field); ?><label class="<?= str_starts_with($field,'page_')||str_contains($field,'description')||$field==='story_text'?'full-width':'' ?>"><?= e(ucwords(str_replace('_',' ',$field))) ?><?php if(in_array($field,['hero_image','story_image','logo','fssai_image'])): ?><?php if($value): ?><img class="admin-image-preview" src="<?= e(asset($value)) ?>" alt="Current image"><?php endif ?><input class="form-control image-input" type="file" name="<?= e($field) ?>" accept="image/jpeg,image/png,image/webp"><?php elseif(str_contains($field,'secret')): ?><input class="form-control" type="password" name="<?= e($field) ?>" autocomplete="new-password" placeholder="<?= $value?'Configured · leave empty to keep':'Not configured' ?>"><?php elseif(in_array($field,['cod_enabled','razorpay_enabled'])): ?><input class="form-check-input ms-2" type="checkbox" name="<?= e($field) ?>" value="1" <?= $value==='1'?'checked':'' ?>><?php elseif($field==='razorpay_mode'): ?><select class="form-select" name="<?= $field ?>"><option value="test" <?= $value==='test'?'selected':'' ?>>Test</option><option value="live" <?= $value==='live'?'selected':'' ?>>Live</option></select><?php elseif(str_starts_with($field,'page_')||str_contains($field,'description')||str_contains($field,'heading')||in_array($field,['story_text','address'])): ?><textarea class="form-control" name="<?= e($field) ?>" rows="<?= str_starts_with($field,'page_')?8:4 ?>"><?= e(str_replace('\\n',"\n",$value)) ?></textarea><?php else: ?><input class="form-control" name="<?= e($field) ?>" value="<?= e(in_array($field,['shipping','free_shipping'])?number_format((int)$value/100,2,'.',''):$value) ?>"><?php if(in_array($field,['shipping','free_shipping'])): ?><small class="muted">Amount in INR</small><?php endif ?><?php endif ?></label><?php endforeach ?></div><button class="btn btn-primary mt-4">Save settings</button></form>
